/// @notice CDPVault._redemptionRate: the lagged fee base (`_laggedSupply`) lags DECREASES only. Principal drawn
/// counts in the base at once, so a draw one transaction before a redemption (same block), repaid and withdrawn
/// one transaction after, is charged against the inflated supply and sets the base rate everyone pays from it;
/// and inside one transaction a repayment of COLD principal, which the `_laggedSupply` NatSpec says counts at
/// once, stays in the base because `_laggedSupplyFrom(_supplyStart())` floors at the start supply.
contract FeeBaseDilutionTest is Test {
    address private constant OTHER = address(0x07E);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    FdBorrower private whale;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new FdAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        FdFeed primary = new FdFeed(uint256(1 ether) * 1e18 / 2000 ether); // IMD = $1
        FdFeed health = new FdFeed(0.85 ether); // mat 170, gap 50
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new FdMirror(primary))
        );
        stable = vault.stablecoin();
        whale = new FdBorrower(vault, imd);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(OTHER, 10_000 ether);
        imd.mint(address(whale), 1_000_000 ether);
        imd.mint(address(vault.treasury()), 10_000 ether); // reserve-funded redemptions
        vm.stopPrank();
        vm.startPrank(OTHER);
        imd.approve(address(vault), type(uint256).max);
        vault.lock(200 ether);
        vault.draw(100 ether);
        stable.transfer(address(whale), 9 ether);
        vm.stopPrank();
        // The honest supply is seasoned: 100 imdUSD held two quiet days.
        vm.warp(block.timestamp + 2 days);
    }

    /// Supply 100. The whale redeems 9 (9% of supply): the base rate is the 4.5% cap. With a 900 draw one
    /// transaction earlier (same block, zero seconds of fee) and a wipe one transaction later, EXPECTED the same
    /// base rate: no seasoned capital was added. ACTUAL: 0.45%, a tenth, for everyone after.
    function test_aOneBlockDrawDilutesTheFeeBaseAcrossTransactions() public {
        uint256 snap = vm.snapshotState();
        whale.cash(9 ether);
        uint256 honest = vault.redemptionBaseRate();
        assertEq(honest, 0.045e18, "9 of 100 over divisor 2 is the 4.5% cap");
        vm.revertToState(snap);

        whale.lockDraw(1_530 ether, 900 ether); // tx 1: 170%, the minimum
        whale.cash(9 ether); // tx 2: charged against a supply of 1,000
        whale.wipe(900 ether); // tx 3: the capital was in the vault for one block
        assertEq(stable.totalSupply(), 91 ether, "the supply is what the honest redemption left");
        assertEq(vault.redemptionBaseRate(), honest, "a draw held one block must not lower the base rate everyone pays");
    }

    /// Transaction 1: the whale draws 900 (cold). Transaction 2: wipe 900 (cold: `_coldRepaidCountsAtOnce`) and
    /// in the SAME call redeem 9. EXPECTED: the 4.5% cap, exactly what the same wipe and cash as two
    /// transactions produce. ACTUAL: 0.45%: the cold 900 burned moments earlier in the same call is still base.
    function test_aColdRepaymentInTheSameTransactionStaysInTheFeeBase() public {
        whale.lockDraw(2_000 ether, 900 ether);
        assertEq(stable.totalSupply(), 1_000 ether);

        uint256 snap = vm.snapshotState();
        whale.wipe(900 ether);
        whale.cash(9 ether);
        uint256 twoTransactions = vault.redemptionBaseRate();
        assertEq(twoTransactions, 0.045e18, "two transactions: the cold 900 left the base at once");
        vm.revertToState(snap);

        whale.wipeThenCash(900 ether, 9 ether);
        assertEq(stable.totalSupply(), 91 ether);
        assertEq(vault.redemptionBaseRate(), twoTransactions, "one transaction must charge what two do");
    }
}

