        router = new SwRouter(vault, imd);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(OTHER, 10_000 ether);
        imd.mint(address(router), 10_000 ether);
        imd.mint(address(vault.treasury()), 5_000 ether); // reserve-funded redemptions
        vm.stopPrank();
        vm.startPrank(OTHER);
        imd.approve(address(vault), type(uint256).max);
